const svgBarChart = (labels, vals, maxV) => {
  const n = labels.length, bw = Math.floor(140 / n), gap = Math.floor(40 / (n + 1));
  const bars = vals.map((v, i) => {
    const bh = Math.round((v / maxV) * 80), bx = 42 + gap + i * (bw + gap), by = 105 - bh;
    return `<rect x="${bx}" y="${by}" width="${bw}" height="${bh}" rx="3" fill="${i%2===0?'#22a381':'#2b7f9c'}" stroke="#0f2b4a" stroke-width="1.5"/><text x="${bx+bw/2}" y="${by-5}" font-size="10" font-weight="bold" fill="#0f2b4a" text-anchor="middle">${v}</text><text x="${bx+bw/2}" y="120" font-size="10" fill="#334155" text-anchor="middle">${labels[i]}</text>`;
  }).join('');
  return gSvg(240, 132, `<line x1="36" y1="15" x2="36" y2="105" stroke="#0f2b4a" stroke-width="2"/><line x1="36" y1="105" x2="225" y2="105" stroke="#0f2b4a" stroke-width="2"/>${bars}`, false);
};

const svgParabola = (a, h, k, lblV='', extra='') => {
  const pts = [];
  for(let px = -9.5; px <= 9.5; px += 0.25) {
    const py = a * (px - h) * (px - h) + k;
    if (py >= -10 && py <= 10) pts.push(`${tX(px).toFixed(1)},${tY(py).toFixed(1)}`);
  }
  const poly = pts.length > 1 ? `<polyline fill="none" stroke="#22a381" stroke-width="3" points="${pts.join(' ')}"/>` : '';
  const vx = tX(h), vy = tY(k);
  return svg(`${poly}${extra}<circle cx="${vx}" cy="${vy}" r="4.5" fill="#e74c3c"/>${lblV ? `<text x="${Math.min(155, Math.max(10, vx + 6))}" y="${Math.max(15, vy - 6)}" font-size="11" font-weight="bold" fill="#0f2b4a">${lblV}</text>` : ''}`);
};

const svgExp = (a, b, asym=0, lblPt='') => {
  const pts = [];
  for(let px = -9; px <= 9; px += 0.25) {
    const py = a * Math.pow(b, px) + asym;
    if (py >= -9.8 && py <= 9.8) pts.push(`${tX(px).toFixed(1)},${tY(py).toFixed(1)}`);
  }
  const poly = pts.length > 1 ? `<polyline fill="none" stroke="#2b7f9c" stroke-width="3" points="${pts.join(' ')}"/>` : '';
  const asLine = `<line x1="0" y1="${tY(asym)}" x2="200" y2="${tY(asym)}" stroke="#e74c3c" stroke-width="1.8" stroke-dasharray="4,3"/>`;
  const y0 = a + asym;
  return svg(`${asLine}${poly}<circle cx="${tX(0)}" cy="${tY(y0)}" r="4.5" fill="#0f2b4a"/>${lblPt ? `<text x="${tX(0)+7}" y="${tY(y0)-5}" font-size="11" font-weight="bold" fill="#0f2b4a">${lblPt}</text>` : ''}`);
};

